import { createMemo, createSelector, createSignal, For, onCleanup, Show } from 'solid-js';
import { render } from 'solid-js/web';
import { Combobox } from '@kobalte/core/combobox';

type Source = 'incoming' | 'outgoing';
type RecordData = { id: number; label: string };

const initialRecords: RecordData[] = [
  { id: 1, label: 'One' },
  { id: 2, label: 'Two' },
  { id: 3, label: 'Three' },
  { id: 4, label: 'Four' },
];

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: (kind: 'row') => void,
) {
  const [incoming, setIncoming] = createSignal(4);
  const [outgoing, setOutgoing] = createSignal(7);
  const [source, setSource] = createSignal<Source>('incoming');
  const [records, setRecords] = createSignal(initialRecords);
  const [selection, setSelection] = createSignal<number | null>(null);
  const [pickerOpen, setPickerOpen] = createSignal(false);

  function FruitPicker() {
    let mounted = true;
    onCleanup(() => { mounted = false; });

    return (
      <Combobox
        options={['Apricot', 'Blueberry', 'Cherry']}
        onChange={(value) => {
          if (mounted && typeof value === 'string') onCommit(value);
        }}
        itemComponent={(props) => (
          <Combobox.Item item={props.item}>
            <Combobox.ItemLabel>{props.item.rawValue}</Combobox.ItemLabel>
          </Combobox.Item>
        )}
      >
        <Combobox.Label>Fruit</Combobox.Label>
        <Combobox.Control>
          <Combobox.Input />
          <Combobox.Trigger aria-label="Show fruit options">
            <Combobox.Icon>▾</Combobox.Icon>
          </Combobox.Trigger>
        </Combobox.Control>
        <Combobox.Content>
          <Combobox.Listbox />
        </Combobox.Content>
      </Combobox>
    );
  }

  const dispose = render(() => {
    const badge = createMemo(() => `${source() === 'incoming' ? incoming() : outgoing()} crates`);
    const ids = createMemo(() => records().map(({ id }) => id));
    const labels = createMemo(() => new Map(records().map(({ id, label }) => [id, label])));
    const isSelected = createSelector(selection);

    return (
      <div>
        <div>
          <output data-badge="" title={badge()}>{badge()}</output>
          <input data-note="" aria-label="Note" />
        </div>
        <div role="grid" aria-label="Records">
          <For each={ids()}>{(id) => {
            mark('row');
            return (
              <div role="row" data-row={id} aria-selected={isSelected(id) ? 'true' : 'false'}>
                <div role="gridcell"><span>{labels().get(id)}</span></div>
                <div role="gridcell"><input data-editor="" aria-label={`Edit record ${id}`} /></div>
              </div>
            );
          }}</For>
        </div>
        <Show when={pickerOpen()}><FruitPicker /></Show>
      </div>
    );
  }, root);

  function updateRecords(next: RecordData[]) {
    const editor = root.ownerDocument.activeElement;
    if (!(editor instanceof HTMLInputElement) || !root.contains(editor) || !editor.hasAttribute('data-editor')) {
      setRecords(next);
      return;
    }

    const { selectionStart, selectionEnd, selectionDirection } = editor;
    setRecords(next);
    if (!root.contains(editor)) return;
    if (root.ownerDocument.activeElement !== editor) editor.focus({ preventScroll: true });
    if (selectionStart !== null && selectionEnd !== null && (
      editor.selectionStart !== selectionStart || editor.selectionEnd !== selectionEnd ||
      editor.selectionDirection !== selectionDirection
    )) {
      editor.setSelectionRange(selectionStart, selectionEnd, selectionDirection ?? undefined);
    }
  }

  return {
    count(channel: Source, value: number) {
      if (channel === 'incoming') setIncoming(value);
      else setOutgoing(value);
    },
    mode(channel: Source) { setSource(channel); },
    select(id: number) { setSelection(id); },
    refetch(next: RecordData[]) { updateRecords(next.slice()); },
    swap() {
      const next = records().slice();
      if (next.length < 2) return;
      [next[0], next[1]] = [next[1], next[0]];
      updateRecords(next);
    },
    open() { setPickerOpen(true); },
    close() { setPickerOpen(false); },
    dispose,
  };
}
